def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all 9's, next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[-2::-1]
        else:
            return left + left[::-1]

    odd = (length % 2 != 0)
    mid = length // 2

    # Split the string into left and right parts
    if odd:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    # Generate palindrome by mirroring left
    pal = make_palindrome(left, odd)
    pal_int = int(pal)

    # If palindrome is strictly greater than num, return it
    if pal_int > num:
        return pal_int

    # Otherwise, increment the left part and then mirror again
    # Increment left part as integer
    left_int = int(left)
    left_int += 1
    left_str = str(left_int)

    # Handle length change after increment (e.g., 999 -> 1000)
    if len(left_str) > len(left):
        # Length increased, so palindrome length increases by 1 or 2
        # For even length, length increases by 1 -> odd length palindrome
        # For odd length, length increases by 1 -> even length palindrome
        # Just construct palindrome of the new length with '1' + zeros + '1'
        return int('1' + ('0' * (length - 1)) + '1')

    # Build palindrome again with incremented left
    pal = make_palindrome(left_str, odd)
    return int(pal)

