def anti_shuffle(s):
    import re

    # Split string into words and spaces, keeping spaces as separate tokens
    tokens = re.findall(r'\S+|\s+', s)
    result = []

    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Determine if token has trailing punctuation
            # Split token into leading word part and trailing punctuation
            # Trailing punctuation: consecutive non-alphanumeric characters at the end
            match = re.match(r'^([A-Za-z0-9]*)([^A-Za-z0-9]*)$', token)
            if match:
                word_part, punct_part = match.groups()
                if word_part:
                    sorted_word = ''.join(sorted(word_part))
                    result.append(sorted_word + punct_part)
                else:
                    # All punctuation? Just append as is
                    result.append(token)
            else:
                # No match fallback, just sort whole token
                result.append(''.join(sorted(token)))
    return ''.join(result)

