def triples_sum_to_zero(l: list):
    n = len(l)
    if n < 3:
        # If fewer than 3 elements, no triplet can be formed, so return False
        return False
    # Sort the list to use two-pointer technique
    l.sort()
    for i in range(n - 2):
        # Avoid duplicates for i
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False

